UPDATE public.posts SET
  slug = 'creme-hidratante-revitalizante-a-base-de-toda-pele-saudavel',
  title = 'Creme Hidratante Revitalizante: A Base de Toda Pele Saudável',
  excerpt = 'Hidratar não é um passo opcional: é o que mantém a barreira da pele forte, confortável e com aquele aspecto saudável. Veja como o Creme Hidratante Revitalizante Rebka entra na sua rotina.',
  content = 'O Creme Hidratante Revitalizante Rebka (30ml) foi desenvolvido para repor a água e os lipídios que a pele perde ao longo do dia. Sua textura é leve, de rápida absorção e não deixa sensação pesada ou oleosa, o que o torna ideal tanto para usar de manhã, antes da maquiagem, quanto à noite, como último passo do skincare. Ao fortalecer a barreira cutânea, ele reduz a sensação de repuxamento, ajuda a controlar a desidratação e deixa a pele mais macia e uniforme desde as primeiras semanas. Como usar: aplique uma quantidade equivalente a uma ervilha sobre o rosto limpo, espalhando com movimentos suaves de dentro para fora e finalizando no colo. Pela manhã, finalize com protetor solar; à noite, aplique depois do sérum para selar os ativos na pele.',
  image_url = '/__l5e/assets-v1/f940fbaa-a3ea-4d01-acf3-1caec967af7c/blog-creme-hidratante.png'
WHERE id = 'a04ce98b-1787-4b2f-93d9-a609084af150';

UPDATE public.posts SET
  slug = 'acido-hialuronico-e-niacinamida-a-dupla-que-transforma-a-pele',
  title = 'Ácido Hialurônico e Niacinamida: A Dupla que Transforma a Pele',
  excerpt = 'Juntos, o ácido hialurônico e a niacinamida do Sérum Hidratante Rebka entregam viço, uniformidade e uma pele visivelmente mais preenchida.',
  content = 'O ácido hialurônico é um ímã de água: ele atrai e retém umidade nas camadas superficiais da pele, resultando em aspecto preenchido, viçoso e linhas finas menos evidentes. A niacinamida atua em outra frente, ajudando a uniformizar o tom, suavizar marcas, controlar a oleosidade e reforçar a barreira cutânea. É por isso que o Sérum Hidratante Rebka (30ml) combina os dois ativos em uma fórmula leve, de toque seco e fácil de encaixar em qualquer rotina. Em que ordem usar: depois da limpeza, aplique o sérum na pele ainda levemente úmida e, em seguida, o Creme Hidratante Revitalizante para selar a hidratação. Pela manhã, finalize sempre com protetor solar — é ele que garante que os resultados dos ativos se mantenham.',
  image_url = '/__l5e/assets-v1/b5dc271a-baea-4fe7-a883-27b65101c4c7/blog-serum-bolhas.png'
WHERE id = 'c65ddfd7-f51e-4487-be18-36e4534a9f16';

UPDATE public.posts SET
  slug = 'serum-hidratante-rebka-como-usar-para-potencializar-os-resultados',
  title = 'Sérum Hidratante Rebka: Como Usar para Potencializar os Resultados',
  excerpt = 'Poucas gotas, no momento certo, fazem toda a diferença. Aprenda o passo a passo para extrair o máximo do Sérum Hidratante Rebka.',
  content = 'Sérum é concentrado: mais produto não significa mais resultado. O ideal são de 3 a 4 gotas do Sérum Hidratante Rebka, distribuídas nas pontas dos dedos e pressionadas suavemente sobre o rosto e o colo — sem esfregar. O melhor momento é logo após a limpeza, com a pele ainda levemente úmida, porque a água ajuda o ácido hialurônico a se fixar e a hidratar em profundidade. De manhã, use o sérum, siga com o Creme Hidratante Revitalizante e finalize com protetor solar. À noite, repita sérum e hidratante para a pele acordar confortável e luminosa. Guarde o frasco ao abrigo do sol e mantenha o conta-gotas sempre fechado para preservar a estabilidade da fórmula. Com uso diário e constante, os resultados de viço e uniformidade aparecem em poucas semanas.',
  image_url = '/__l5e/assets-v1/3326836d-23a9-45e6-9d0c-67c8a00e1d3a/blog-serum-splash.png'
WHERE id = '553d3fbb-0e54-4439-95ed-b6953d707501';